package com.jhcomp.prospect.shared.persistence;

import java.util.UUID;

import org.springframework.data.domain.Persistable;

import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;

/**
 * The base of entities whose id is generated by the application.
 *
 * <p>With the id already filled in, Spring Data cannot tell a new entity from
 * an existing one and treats every {@code save} as a possible update: it runs
 * a {@code SELECT} before each {@code INSERT} and returns a copy rather than
 * the instance it stored. On an import of two thousand rows with leads that
 * was around ten thousand extra queries. Marking the entity as new until it is
 * stored or loaded goes straight to the {@code INSERT}.
 */
@MappedSuperclass
public abstract class AssignedIdEntity implements Persistable<UUID> {

    @Id
    private UUID id;

    @Transient
    private boolean isNew = true;

    protected AssignedIdEntity() {
        // Required by JPA.
    }

    protected AssignedIdEntity(UUID id) {
        this.id = id;
    }

    @Override
    public UUID getId() {
        return id;
    }

    @Override
    public boolean isNew() {
        return isNew;
    }

    @PostLoad
    @PostPersist
    void markPersisted() {
        this.isNew = false;
    }
}
